-- KO-348: visual-learning rollout for Chapters 01–03.
-- Illustrative diagrams only; no market data, return promises, or recommendations.
BEGIN;

WITH blocks(slug, block_type, data_status, content) AS (VALUES
('assets-vs-liabilities','comparison','illustrative',$json${"en":{"icon":"⚖️","eyebrow":"Balance sheet","title":"What you own and what you owe are different columns","altText":"A two-column comparison separates owned value from obligations.","disclosure":"Illustrative snapshot only — values and categories depend on your situation.","payload":{"leftTitle":"Assets ✅","rightTitle":"Liabilities 📌","rows":[{"left":"Cash you own","right":"Bill you must pay"},{"left":"Savings balance","right":"Loan balance"},{"left":"Can add to your net position","right":"Reduces your net position"}]}},"id":{"icon":"⚖️","eyebrow":"Neraca sederhana","title":"Yang dimiliki dan yang terutang adalah kolom berbeda","altText":"Perbandingan dua kolom memisahkan nilai yang dimiliki dari kewajiban.","disclosure":"Potret ilustratif saja — nilai dan kategori bergantung pada kondisi Anda.","payload":{"leftTitle":"Aset ✅","rightTitle":"Liabilitas 📌","rows":[{"left":"Kas yang dimiliki","right":"Tagihan yang harus dibayar"},{"left":"Saldo tabungan","right":"Saldo pinjaman"},{"left":"Dapat menambah posisi bersih","right":"Mengurangi posisi bersih"}]}}}$json$::jsonb),
('income-vs-wealth','comparison','illustrative',$json${"en":{"icon":"📊","eyebrow":"Flow and snapshot","title":"Income moves; wealth is a position","altText":"A comparison distinguishes money received over a month from assets minus liabilities at a point in time.","disclosure":"Illustrative example only — neither number alone describes financial wellbeing.","payload":{"leftTitle":"Income 💼","rightTitle":"Wealth 🧰","rows":[{"left":"Received over time","right":"Measured at a point in time"},{"left":"Rp6m this month","right":"Assets minus liabilities"},{"left":"Can change next month","right":"Can change as assets or debt change"}]}},"id":{"icon":"📊","eyebrow":"Arus dan potret","title":"Pendapatan bergerak; kekayaan adalah posisi","altText":"Perbandingan membedakan uang yang diterima selama sebulan dari aset dikurangi liabilitas pada suatu waktu.","disclosure":"Contoh ilustratif saja — satu angka tidak menggambarkan kesejahteraan keuangan.","payload":{"leftTitle":"Pendapatan 💼","rightTitle":"Kekayaan 🧰","rows":[{"left":"Diterima selama waktu","right":"Diukur pada satu waktu"},{"left":"Rp6 juta bulan ini","right":"Aset dikurangi liabilitas"},{"left":"Dapat berubah bulan depan","right":"Berubah saat aset atau utang berubah"}]}}}$json$::jsonb),
('time-value-of-money','process','calculated',$json${"en":{"icon":"⏳","eyebrow":"Time changes choices","title":"A rupiah today can be used, saved, or compared with later","altText":"A three-step time arrow shows money today, a choice to save or spend, and a later outcome.","disclosure":"Illustrative learning example; rates, prices, and outcomes vary.","payload":{"steps":[{"title":"1. Today","description":"Rp100k can solve a need now or be set aside."},{"title":"2. Time passes","description":"Prices, interest, and opportunities can change."},{"title":"3. Compare later","description":"Ask what the money can do at each point in time."}]}},"id":{"icon":"⏳","eyebrow":"Waktu mengubah pilihan","title":"Rupiah hari ini dapat dipakai, ditabung, atau dibandingkan dengan nanti","altText":"Panah waktu tiga langkah menunjukkan uang hari ini, pilihan menabung atau belanja, dan hasil nanti.","disclosure":"Contoh pembelajaran ilustratif; suku bunga, harga, dan hasil dapat berbeda.","payload":{"steps":[{"title":"1. Hari ini","description":"Rp100 ribu dapat memenuhi kebutuhan sekarang atau disisihkan."},{"title":"2. Waktu berjalan","description":"Harga, bunga, dan kesempatan dapat berubah."},{"title":"3. Bandingkan nanti","description":"Tanyakan apa yang dapat dilakukan uang pada setiap waktu."}]}}}$json$::jsonb),
('understanding-risk','process','illustrative',$json${"en":{"icon":"🛟","eyebrow":"Risk check","title":"Before acting, ask what could go wrong","altText":"A three-step risk flow asks about possible loss, ability to handle it, and time needed.","disclosure":"Risk is not a prediction or a guarantee; this is a decision framework.","payload":{"steps":[{"title":"1. Name the downside","description":"What could fall, be delayed, or cost more?"},{"title":"2. Check your buffer","description":"Could you handle that outcome without harming essentials?"},{"title":"3. Match the timeline","description":"Money needed soon has less room for uncertainty."}]}},"id":{"icon":"🛟","eyebrow":"Cek risiko","title":"Sebelum bertindak, tanyakan apa yang bisa salah","altText":"Alur risiko tiga langkah menanyakan kemungkinan rugi, kemampuan menanggungnya, dan waktu yang dibutuhkan.","disclosure":"Risiko bukan prediksi atau jaminan; ini kerangka pengambilan keputusan.","payload":{"steps":[{"title":"1. Sebutkan sisi buruk","description":"Apa yang dapat turun, tertunda, atau lebih mahal?"},{"title":"2. Cek penyangga","description":"Bisakah Anda menghadapi hasil itu tanpa mengganggu kebutuhan pokok?"},{"title":"3. Cocokkan waktunya","description":"Uang yang dibutuhkan segera punya ruang lebih kecil untuk ketidakpastian."}]}}}$json$::jsonb),
('value-and-purchasing-power','worked_example','calculated',$json${"en":{"icon":"🛒","eyebrow":"Purchasing-power chart","title":"The same budget can reach fewer items","altText":"A before-and-after calculation shows Rp100,000 buying five Rp20,000 items before a price rise and four Rp25,000 items after.","disclosure":"Calculated illustration only; real prices vary by item, place, and time.","payload":{"inputs":[{"label":"Before","value":"5 × Rp20k = Rp100k"},{"label":"After","value":"5 × Rp25k = Rp125k"}],"steps":["The same five-item basket costs Rp25k more.","Rp100k now covers four items at Rp25k each."],"outcome":"Purchasing power falls when the same money reaches fewer goods."}} ,"id":{"icon":"🛒","eyebrow":"Grafik daya beli","title":"Anggaran yang sama dapat menjangkau lebih sedikit barang","altText":"Perhitungan sebelum dan sesudah menunjukkan Rp100.000 membeli lima barang Rp20.000 sebelum kenaikan harga dan empat barang Rp25.000 sesudahnya.","disclosure":"Ilustrasi perhitungan saja; harga nyata berbeda menurut barang, tempat, dan waktu.","payload":{"inputs":[{"label":"Sebelum","value":"5 × Rp20 ribu = Rp100 ribu"},{"label":"Sesudah","value":"5 × Rp25 ribu = Rp125 ribu"}],"steps":["Keranjang lima barang menjadi Rp25 ribu lebih mahal.","Rp100 ribu kini mencakup empat barang seharga Rp25 ribu."],"outcome":"Daya beli turun saat uang yang sama menjangkau lebih sedikit barang."}}}$json$::jsonb),
('behavioral-bias-intro','process','illustrative',$json${"en":{"icon":"🧠","eyebrow":"Pause loop","title":"Notice the feeling before the decision","altText":"A three-step flow says pause, name the feeling, then check facts and goal.","disclosure":"Illustrative decision tool, not a diagnosis.","payload":{"steps":[{"title":"1. Pause","description":"Urgency, fear, or excitement can narrow attention."},{"title":"2. Name it","description":"Is this fear of missing out, loss fear, or a habit?"},{"title":"3. Check","description":"Return to facts, your goal, and a calm next step."}]}},"id":{"icon":"🧠","eyebrow":"Lingkar jeda","title":"Sadari perasaan sebelum mengambil keputusan","altText":"Alur tiga langkah berbunyi berhenti, sebutkan perasaan, lalu cek fakta dan tujuan.","disclosure":"Alat keputusan ilustratif, bukan diagnosis.","payload":{"steps":[{"title":"1. Berhenti","description":"Desakan, takut, atau antusias dapat mempersempit perhatian."},{"title":"2. Sebutkan","description":"Apakah ini takut ketinggalan, takut rugi, atau kebiasaan?"},{"title":"3. Cek","description":"Kembali ke fakta, tujuan Anda, dan langkah yang tenang."}]}}}$json$::jsonb),
('pay-yourself-first','process','illustrative',$json${"en":{"icon":"🏦","eyebrow":"Pay-yourself-first flow","title":"Reserve a goal before flexible spending","altText":"An income allocation flow sets aside a small planned amount before remaining spending.","disclosure":"Illustrative budgeting pattern; adapt amounts to essentials and circumstances.","payload":{"steps":[{"title":"1. Income arrives","description":"Start with what is actually available."},{"title":"2. Reserve a planned amount","description":"Move a realistic amount toward a goal or buffer."},{"title":"3. Spend the remainder intentionally","description":"Keep essentials visible before flexible choices."}]}},"id":{"icon":"🏦","eyebrow":"Alur bayar diri sendiri","title":"Sisihkan tujuan sebelum belanja fleksibel","altText":"Alur pembagian pendapatan menyisihkan jumlah kecil yang direncanakan sebelum pengeluaran lainnya.","disclosure":"Pola anggaran ilustratif; sesuaikan jumlah dengan kebutuhan pokok dan kondisi.","payload":{"steps":[{"title":"1. Pendapatan masuk","description":"Mulai dari jumlah yang benar-benar tersedia."},{"title":"2. Sisihkan jumlah terencana","description":"Pindahkan jumlah realistis ke tujuan atau penyangga."},{"title":"3. Belanjakan sisa dengan sadar","description":"Pastikan kebutuhan pokok terlihat sebelum pilihan fleksibel."}]}}}$json$::jsonb),
('spending-traps','process','illustrative',$json${"en":{"icon":"🛒","eyebrow":"Checkout pause","title":"Put a pause between a trigger and checkout","altText":"A flow maps a trigger to a pause, a goal check, and a deliberate choice.","disclosure":"Illustrative habit tool; no purchase is automatically right or wrong.","payload":{"steps":[{"title":"1. Notice the trigger","description":"A sale timer, social post, or boredom can start an impulse."},{"title":"2. Pause","description":"Wait long enough to compare the purchase with your plan."},{"title":"3. Choose deliberately","description":"Buy, delay, or skip based on needs, goals, and budget."}]}},"id":{"icon":"🛒","eyebrow":"Jeda checkout","title":"Beri jeda antara pemicu dan checkout","altText":"Alur memetakan pemicu ke jeda, cek tujuan, dan pilihan sadar.","disclosure":"Alat kebiasaan ilustratif; tidak ada pembelian yang otomatis benar atau salah.","payload":{"steps":[{"title":"1. Sadari pemicu","description":"Timer diskon, unggahan sosial, atau bosan dapat memicu impuls."},{"title":"2. Beri jeda","description":"Tunggu cukup lama untuk membandingkan pembelian dengan rencana."},{"title":"3. Pilih dengan sadar","description":"Beli, tunda, atau lewati berdasarkan kebutuhan, tujuan, dan anggaran."}]}}}$json$::jsonb),
('check-ojk-license','process','source_derived',$json${"en":{"icon":"🏛️","eyebrow":"Independent check","title":"Check an offer through an official OJK channel","altText":"A verification flow says copy the name, use an official OJK channel, and compare the result before acting.","disclosure":"Use official OJK information for a real offer; this visual does not certify any provider.","payload":{"steps":[{"title":"1. Keep the details","description":"Record the company, product, and claim."},{"title":"2. Check independently","description":"Use an official OJK channel, not a promoter's link."},{"title":"3. Pause if unclear","description":"Do not send money or credentials under pressure."}]}},"id":{"icon":"🏛️","eyebrow":"Cek mandiri","title":"Periksa penawaran lewat kanal resmi OJK","altText":"Alur verifikasi berbunyi salin nama, gunakan kanal resmi OJK, lalu bandingkan hasil sebelum bertindak.","disclosure":"Gunakan informasi resmi OJK untuk penawaran nyata; visual ini tidak mengesahkan penyedia mana pun.","payload":{"steps":[{"title":"1. Simpan detail","description":"Catat perusahaan, produk, dan klaim."},{"title":"2. Cek mandiri","description":"Gunakan kanal resmi OJK, bukan tautan promotor."},{"title":"3. Berhenti bila tidak jelas","description":"Jangan kirim uang atau kredensial saat ditekan."}]}}}$json$::jsonb),
('mlm-pyramid-red-flags','comparison','illustrative',$json${"en":{"icon":"🚩","eyebrow":"Claim check","title":"Look for product value, not recruitment pressure","altText":"A comparison contrasts clear product value and transparent terms with pressure to recruit or buy quickly.","disclosure":"Illustrative warning signs; check a real offer independently.","payload":{"leftTitle":"Check carefully 🔎","rightTitle":"Pause on pressure 🚩","rows":[{"left":"Clear product and terms","right":"Main message is recruiting others"},{"left":"Time to verify","right":"Urgency or secrecy"},{"left":"Independent information","right":"Claims only from the promoter"}]}},"id":{"icon":"🚩","eyebrow":"Cek klaim","title":"Cari nilai produk, bukan tekanan rekrutmen","altText":"Perbandingan membedakan nilai produk dan syarat jelas dari tekanan merekrut atau membeli cepat.","disclosure":"Tanda peringatan ilustratif; periksa penawaran nyata secara mandiri.","payload":{"leftTitle":"Periksa dengan teliti 🔎","rightTitle":"Berhenti saat ditekan 🚩","rows":[{"left":"Produk dan syarat jelas","right":"Pesan utama adalah merekrut orang lain"},{"left":"Ada waktu untuk verifikasi","right":"Desakan atau kerahasiaan"},{"left":"Informasi mandiri","right":"Klaim hanya dari promotor"}]}}}$json$::jsonb),
('phishing-social-engineering','process','illustrative',$json${"en":{"icon":"🔐","eyebrow":"Safety flow","title":"Stop, verify, then report","altText":"A safety flow says do not click or share a code, verify through an official route, and report suspicious contact.","disclosure":"Never share a password, PIN, or OTP because of a message.","payload":{"steps":[{"title":"1. Stop","description":"Do not click a rushed link or share a code."},{"title":"2. Verify","description":"Contact the organisation using an official app, site, or number."},{"title":"3. Report","description":"Use the official reporting route and warn the right people."}]}},"id":{"icon":"🔐","eyebrow":"Alur aman","title":"Berhenti, verifikasi, lalu laporkan","altText":"Alur aman menyatakan jangan klik atau bagikan kode, verifikasi lewat jalur resmi, dan laporkan kontak mencurigakan.","disclosure":"Jangan pernah membagikan kata sandi, PIN, atau OTP karena pesan.","payload":{"steps":[{"title":"1. Berhenti","description":"Jangan klik tautan mendesak atau bagikan kode."},{"title":"2. Verifikasi","description":"Hubungi organisasi melalui aplikasi, situs, atau nomor resmi."},{"title":"3. Laporkan","description":"Gunakan jalur pelaporan resmi dan beri tahu pihak yang tepat."}]}}}$json$::jsonb),
('too-good-to-be-true','process','illustrative',$json${"en":{"icon":"🔎","eyebrow":"Reality check","title":"Extraordinary claims deserve extra checking","altText":"A three-step checklist asks what is promised, what evidence is independent, and what pressure is being used.","disclosure":"No investment outcome is guaranteed; verify independently before acting.","payload":{"steps":[{"title":"1. Read the claim","description":"Guaranteed profit or no-risk language is a reason to pause."},{"title":"2. Seek independent evidence","description":"Do not rely only on screenshots, testimonials, or a group chat."},{"title":"3. Protect your data","description":"Never send money, passwords, PINs, or OTPs under pressure."}]}},"id":{"icon":"🔎","eyebrow":"Cek kenyataan","title":"Klaim luar biasa perlu pemeriksaan lebih","altText":"Daftar periksa tiga langkah menanyakan apa yang dijanjikan, bukti mandiri, dan tekanan yang digunakan.","disclosure":"Tidak ada hasil investasi yang dijamin; verifikasi mandiri sebelum bertindak.","payload":{"steps":[{"title":"1. Baca klaim","description":"Bahasa untung pasti atau tanpa risiko adalah alasan untuk berhenti."},{"title":"2. Cari bukti mandiri","description":"Jangan hanya mengandalkan tangkapan layar, testimoni, atau grup chat."},{"title":"3. Lindungi data","description":"Jangan kirim uang, kata sandi, PIN, atau OTP saat ditekan."}]}}}$json$::jsonb)
)
INSERT INTO public.lesson_visual_blocks (lesson_id, placement, block_type, content, data_status, display_order, is_published)
SELECT lesson.id, 'concept', blocks.block_type, blocks.content, blocks.data_status, 10, TRUE
FROM blocks JOIN public.lessons lesson ON lesson.slug=blocks.slug
WHERE lesson.is_published
ON CONFLICT (lesson_id, placement, display_order) DO UPDATE SET block_type=EXCLUDED.block_type, content=EXCLUDED.content, data_status=EXCLUDED.data_status, is_published=TRUE;
COMMIT;
